const BUILD = "CDF-V12.7-DIRECT-EDITOR";
const THREE_VERSION = "0.181.2";
const GAME_HTML_B64 = "";

function decodeHtml() {
  const bin = atob(GAME_HTML_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}
function text(body,status=200,extra={}) {
  return new Response(body,{status,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store",...extra}});
}
async function fetchVendor(request, url) {
  const prefix = "/vendor/three/";
  const rel = url.pathname.slice(prefix.length);
  if (!rel || rel.includes("..") || !/^[A-Za-z0-9_./-]+$/.test(rel)) return text("Invalid vendor path",400);
  const candidates = [
    `https://cdn.jsdelivr.net/npm/three@${THREE_VERSION}/${rel}`,
    `https://unpkg.com/three@${THREE_VERSION}/${rel}`
  ];
  let last = "";
  for (const upstream of candidates) {
    try {
      const r = await fetch(upstream, { redirect:"follow", headers:{accept:"*/*"} });
      if (!r.ok) { last = `${upstream} -> HTTP ${r.status}`; continue; }
      const h = new Headers(r.headers);
      h.set("cache-control","public,max-age=86400");
      h.set("access-control-allow-origin","*");
      h.set("x-cdf-build",BUILD);
      h.set("x-cdf-upstream",upstream.includes("jsdelivr")?"jsdelivr":"unpkg");
      if (rel.endsWith('.js')) h.set("content-type","text/javascript; charset=utf-8");
      return new Response(r.body, {status:200,headers:h});
    } catch(e) { last = `${upstream} -> ${e?.message||e}`; }
  }
  return text("VENDOR_FETCH_FAILED\n"+last,502,{"x-cdf-build":BUILD});
}
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/build-id.txt") return text(BUILD+"\n",200,{"x-cdf-build":BUILD});
    if (url.pathname === "/__cdf_status") return new Response(JSON.stringify({build:BUILD,worker:true,three:THREE_VERSION,path:url.pathname},null,2),{headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-cdf-build":BUILD}});
    if (url.pathname === "/vendor-check") {
      const testUrl = new URL("/vendor/three/build/three.module.js", url);
      const r = await fetchVendor(new Request(testUrl), testUrl);
      const body = await r.text();
      return text(`BUILD=${BUILD}\nSTATUS=${r.status}\nUPSTREAM=${r.headers.get('x-cdf-upstream')||'none'}\nBYTES=${body.length}\nPREFIX=${body.slice(0,80).replace(/\s+/g,' ')}` , r.ok?200:502, {"x-cdf-build":BUILD});
    }
    if (url.pathname.startsWith("/vendor/three/")) return fetchVendor(request,url);
    if (request.method !== "GET" && request.method !== "HEAD") return text("Method not allowed",405);
    const headers = {
      "content-type":"text/html; charset=utf-8",
      "cache-control":"no-store, no-cache, must-revalidate, max-age=0",
      "pragma":"no-cache",
      "expires":"0",
      "x-cdf-build":BUILD
    };
    return new Response(request.method === "HEAD" ? null : decodeHtml(), {status:200,headers});
  }
};
